t1=None
def control(obs):
    global ph,c0,t1
    t=obs['t']; h=obs['hitch_deg']; cov=obs['progress']['covered']; v=obs['motion']['v_mps']
    if c0 is None: c0=cov
    if obs['motion']['hold_s']>0.05: return (0.0,0.0,-41)
    if ph==0:
        if c0-cov>=3.5:
            ph=1; t1=t
        return (0.0,1.2,-41)
    if ph==1:
        if t-t1>1.5 and abs(v)<0.05:
            ph=2
        return (0.0,0.0,-41)
    tgt=-32.0 if cov<33 else -12.0
    s=max(-42.0,min(42.0,2.0*(h-tgt)))
    return (s,-0.7,-41)

